def fresh_scenarios() -> list[FreshReportScenario]:
    """Return balanced training-only evidence interleaved by decision category."""
    result = []
    for index in range(max(map(len, _CASES.values()))):
        for classification, pairs in _CASES.items():
            if index < len(pairs):
                scope, report = pairs[index]
                category = classification
                result.append(FreshReportScenario(
                    key=f'fresh-v2-{category.lower()}-{index + 1:02d}',
                    split='train', scope=scope, report=report, expected=category,
                ))
    return result
